import * as THREE from 'three/webgpu';
import { texture, uv, vec4 } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-label-1';
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const imgTex = ctx.textureLoader.load('/prism-mock/home/nodes/cta-hero-isolated.png');
  imgTex.colorSpace = THREE.SRGBColorSpace;

  const rectU0 = 0 / 512;
  const rectV0 = 1 - (0 + 320) / 320;
  const rectU1 = (0 + 512) / 512;
  const rectV1 = 1 - 0 / 320;

  const uvNode = uv();
  const remappedU = uvNode.x.mul(rectU1 - rectU0).add(rectU0);
  const remappedV = uvNode.y.mul(rectV1 - rectV0).add(rectV0);
  const remappedUV = uvNode.toVar();
  remappedUV.x = remappedU;
  remappedUV.y = remappedV;

  material.colorNode = texture(imgTex, remappedUV);
  material.opacityNode = texture(imgTex, remappedUV).a;

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'features-card-1-image';
  group.add(plane);

  let textMesh = null;
  try {
    textMesh = createTextMesh({
      text: 'Features 1',
      font: 'Lora',
      weight: 400,
      sizePx: 39,
      color: config?.visualSpec?.colors?.paper ?? '#e8ecf2',
      fontAtlas: ctx.fontAtlas,
      maxWidth: width * 0.9
    });
    textMesh.name = 'features-card-1-headline';
    textMesh.position.set(0, -height / 2 - 0.14, 0.01);
    group.add(textMesh);
  } catch (e) {
    // fontAtlas unavailable — skip text render gracefully
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (imgTex && imgTex.dispose) imgTex.dispose();
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) {
        if (Array.isArray(textMesh.material)) {
          textMesh.material.forEach(m => m.dispose());
        } else {
          textMesh.material.dispose();
        }
      }
    }
  };

  return group;
}
